try {
 const data = global.get('robocar').decode(msg.payload);
 data.receivedAt = Date.now();
 data.receivedIso = new Date(data.receivedAt).toISOString();
 data.topic = msg.topic;
 const log = {payload: JSON.stringify(data)};
 // Events are historical records; they must not refresh the live display.
 if (msg.topic.endsWith('/events')) return [null, log];
 const previous = context.get('previous');
 if (previous && previous.bootId === data.bootId) {
   const step = (data.sequence - previous.sequence) >>> 0;
   // Within one boot, sequence comparison is unsigned and wrap-safe.
   if (step === 0 || step >= 0x80000000)
     return [null, log];
 }
 context.set('previous', data);
 msg.payload = data;
 return [msg, log];
} catch (e) { node.warn(e.message); return null; }
